import { Code, Code2, Code2Icon, CodeSquare, Cpu, CpuIcon, Database, GitBranch, Handshake, Monitor, Palette, Server, Sparkles, Terminal, Wand2, Zap } from 'lucide-react'
import React, { use } from 'react'

const Skills = ({ data }) => {

   const [userData , setUserData] = React.useState([]);
   const skills = userData[0]?.skills;

   React.useEffect(() => {
     setUserData(data); 

      },[data]);
      



  return <div className='mt-12 '>
    <h3>My Skills </h3>
    <div className=' grid grid-cols-3 grid-rows-2 gap-y-8 gap-x-20 mt-8 w-fit mx-auto ' >
        {/* Frontend skills  */}


        {
          skills && skills?.map((skills,index)=>{
            return (
        <div  className='flex flex-col p-4   h-72 w-[26rem] border-2 border-text'key={index} >
         
            <h4 className="flex flex-row  gap-2 items-center mx-auto">Frontend Skills </h4>
            <div className='mt-4'>
              <ul className=' flex flex-col gap-2'>
                 <li> <span> ➤ </span> HTML </li>
                 <li> <span> ➤ </span> CSS </li>
                 <li> <span> ➤ </span> Tailwind </li>
                 <li> <span> ➤ </span> React JS </li>
                 <li> <span> ➤ </span> Angular JS </li>
                 <li> <span> ➤ </span> Java Script </li>
                 <li> <span> ➤ </span> Type Script </li>
              </ul>
            </div>
         
        </div>
            )
          })
        }
        
        {/* backend skills  */}
       
        {/* Data Base  */}
       
        {/* DEVOPS AND TOOLS */}
       
        {/* SOFT SKILLS */}
       
    
        {/* OTHERS */}
       
       
    </div>
  </div>
  
}

export default Skills
